// Send product image via WAHA API
const chatId = $json.chatId;
const imageUrl = $json.imageUrl;
const replyText = String($json.replyText || '');
const session = $env.PILOT_WAHA_SESSION;
const wahaUrl = $env.WAHA_BASE_URL;
const apiKey = $env.WAHA_API_KEY;

const result = await this.helpers.httpRequest({
  method: 'POST',
  url: wahaUrl + '/api/sendImage',
  json: true,
  headers: {
    'X-Api-Key': apiKey
  },
  body: {
    session: session,
    chatId: chatId,
    file: { url: imageUrl },
    caption: replyText
  }
});

return [{ json: result }];

let ctx = {};
try {
  ctx = $('Prepare AI Input').item.json;
} catch(e) {
  try {
    ctx = $('Out of Stock Path').item.json;
  } catch(e2) {}
}

const replyText = $input.item.json.text || $input.item.json.output;
const products = JSON.parse(ctx.products_json ?? '[]');
const messageText = (ctx.messageText ?? '').toLowerCase();

// Only send image if:
// 1. User explicitly asked for a photo/image/picture, OR
// 2. Exactly 1 specific product was matched (not a general "what do you have" query)
const isPhotoRequest = /photo|image|picture|show|see|look|view|pic/i.test(messageText);
const isSingleProduct = products.length === 1;
const firstProduct = products[0];

let hasImage = false;
let imageUrl = '';

if (firstProduct && firstProduct.image_url && (isPhotoRequest || isSingleProduct)) {
  hasImage = true;
  imageUrl = firstProduct.image_url;
}

return {
  json: {
    replyText: replyText,
    hasImage: hasImage,
    imageUrl: imageUrl,
    chatId: ctx.chatId,
    session: ctx.session
  }
};
